from pathlib import Path
import re, itertools, collections, math
root = Path('content/catalog/finite-groups/sporadic')
for n,t,k,expected,seed in [(11,4,5,66,(1,2,3,4,5)),(12,5,6,132,(1,2,3,4,5,9)),(22,3,6,77,(1,2,3,10,18,20)),(23,4,7,253,(1,2,3,4,5,11,17)),(24,5,8,759,(1,2,3,4,5,11,17,24))]:
    text = (root / f'm{n}.knowl.md').read_text()
    display = text.split(r'\begin{aligned}',1)[1].split(r'\end{aligned}',1)[0]
    atext,btext = display.split('b&=')
    gens = []
    for part in (atext,btext):
        p = list(range(n+1))
        for cycle in re.findall(r'\(([^()]*)\)',part):
            c = list(map(int,re.findall(r'\d+',cycle)))
            for x,y in zip(c,c[1:]+c[:1]):
                p[x] = y
        gens.append(p)
    orbit = {seed}
    todo = [seed]
    while todo:
        block = todo.pop()
        for p in gens:
            image = tuple(sorted(p[x] for x in block))
            if image not in orbit:
                orbit.add(image)
                todo.append(image)
    counts = collections.Counter(subset for block in orbit for subset in itertools.combinations(block,t))
    assert len(orbit) == expected, (n,len(orbit),expected)
    assert len(counts) == math.comb(n,t) and set(counts.values()) == {1}
    print(f'M{n}: displayed permutations give all {expected} blocks of S({t},{k},{n}); each {t}-subset appears once')
